        void SpellHit(Unit* pCaster, const SpellInfo* pSpell) override
        {
            if (!m_bIsDuelInProgress && pSpell->Id == SPELL_DUEL)
            {
                m_uiDuelerGUID = pCaster->GetGUID();
                m_bIsDuelInProgress = true;
            }
        }

        void DamageTakenAfterScaling(Unit* attacker, uint32& damage, DamageEffectType /*type*/) override
        {
            if (!m_bIsDuelInProgress)
                return;
            Player* player = attacker ? attacker->GetAffectingPlayer() : nullptr;
            if (!player || !player->IsInWorld() || !player->IsAlive() || player->GetMap() != me->GetMap() ||
                player->GetGUID() != m_uiDuelerGUID || lose)
            {
                damage = 0;
                return;
            }
            if (damage < me->GetHealth(attacker))
                return;
            damage = 0;
            lose = true;
            player->KilledMonsterCredit(108722);
            player->RemoveGameObject(SPELL_DUEL_FLAG, true);
            player->AttackStop();
            if (attacker != player)
                attacker->AttackStop();
            me->CastSpell(player, SPELL_DUEL_VICTORY, true);
            me->CastSpell(me, 7267, true);
            me->RestoreFaction();
        }

        void UpdateAI(uint32 uiDiff) override
        {
            if (m_bIsDuelInProgress && !lose)
            {
                Player* player = ObjectAccessor::GetPlayer(*me, m_uiDuelerGUID);
                if (!player || !player->IsAlive())
                {
                    EnterEvadeMode();
                    return;
                }
            }

            if (!UpdateVictim())
            {
                if (m_bIsDuelInProgress)
                {
                    if (m_uiDuelTimer <= uiDiff)
                    {
                        me->setFaction(FACTION_HOSTILE);

                        if (Unit* unit = Unit::GetUnit(*me, m_uiDuelerGUID))
                            AttackStart(unit);
                    }
                    else
                        m_uiDuelTimer -= uiDiff;
                }
                return;
            }

            if (m_bIsDuelInProgress)
            {
                if (lose)
                {
                    if (!me->HasAura(7267))
                        EnterEvadeMode();
                    return;
                }
                else if (me->getVictim() && me->getVictim()->GetTypeId() == TYPEID_PLAYER && me->getVictim()->HealthBelowPct(10))
                {
                    me->getVictim()->CastSpell(me->getVictim(), 7267, true); // beg
                    me->getVictim()->RemoveGameObject(SPELL_DUEL_FLAG, true);
                    EnterEvadeMode();
                    return;
                }

                if (!UpdateVictim() || me->HasUnitState(UNIT_STATE_CASTING))
                    return;

                if (spelltimer <= uiDiff)
                {
                    uint32 spell = 0;
                    switch (me->GetEntry())
                    {
                        case 108752:
                            spell = 172673;
                            spelltimer = 2000;
                            break;
                        case 108765:
                            spell = 198623;
                            spelltimer = 2000;
                            break;
                        case 108767:
                        case 108750:
                            spell = 172757;
                            spelltimer = 11000;
                            break;
                        case 108723:
                            spell = 171777;
                            spelltimer = 5500;
                            break;
                        default:
                            break;
                    }
                    if (spell > 0)
                        DoCast(spell);
                }
                else
                    spelltimer -= uiDiff;
            }

            // TODO: spells

            CombatAI::UpdateAI(uiDiff);
        }
    }

