        uiBlazeTimer = 5;
    }

    void DoAction(int32 const action) override
    {
        switch (action)
        {
        case ACTION_REPENTANCE_START:
            me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_NON_ATTACKABLE);
            me->SetReactState(REACT_PASSIVE);
            me->AttackStop();
